from taf.internal.aliasing import aliasing_scope
from .facade import BmcConnection


class bmc(object):
    """
    Robot interface with keywords for BMC client.
    """
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    lookup_handler, store = aliasing_scope('connection', BmcConnection, name=__name__)

    def connect_to(self, address, username, password, port=443, name=None, interface='redfish_rm_17'):
        """
        Keyword initiates connection to desired BMC interface.

        If name is provided, alias is created for the value,
        which can be used in methods as string instead of Connection object.

        NOTE: If name is not provided, the connection becomes default when calling
        methods with no connection parameter provided.

        :param str address: BMC interface ip address ie. 127.0.0.1
        :param int port: Port number, Default is 443
        :param str username: BMC endpoint username
        :param str password: BMC endpoint password for username
        :param str name: (Optional) Name of alias for returned connection. If not provided, this connection becomes default.
        :param str interface: (Optional) Version of BMC interface (default is AirFrame Redfish RM17)
                              Supported versions: 'redfish_rm_17', 'redfish_oe_19', 'redfish_oe_20', 'redfish_oe_22'
        :return: BmcConnection object, for BMC interface
        """
        connection = BmcConnection(
            address=address,
            port=port,
            username=username,
            password=password,
            interface=interface
        )
        self.store.add(connection, name)
        return connection

    @lookup_handler.implicit_lookup
    def disconnect(self, connection=None):
        """
        Keyword performs disconnect on given BMC Connection.

        :param connection: BmcConnection object or if used, string name alias
        :return: Nothing
        """
        connection.disconnect()

    @lookup_handler.implicit_lookup
    def power_off_immediate(self, connection=None):
        """
        Keyword that performs "poweroff" on the endpoint system.

        Result BmcResponse object content example:
            >>> result.status
            >>> 200
            >>> result.dict
            >>> {'System reset result': 'Success.'}

        :param connection: BmcConnection object or if used, string name alias
        :return: taf.internal.bmc.interfaces.bmc.BmcResponse with action result.
        """
        return connection.computer_system_reset_forceoff()

    @lookup_handler.implicit_lookup
    def power_on(self, connection=None):
        """
        Keyword performs "power on" on the endpoint system.

        Result BmcResponse object content example:
            >>> result.status
            >>> 200
            >>> result.dict
            >>> {'System reset result': 'Success.'}

        :param connection: BmcConnection object or if used, string name alias
        :return: taf.internal.bmc.interfaces.bmc.BmcResponse with action result.
        """
        return connection.computer_system_on()
